public interface IReservationService {
    Reservation create(Reservation reservation);

    Reservation findById(Long id);

    List<Reservation> findAll();

    Reservation update(Long id, Reservation reservation);

    void deleteById(Long id);
}

public abstract class ReservationServiceDecorator implements IReservationService {

    protected final IReservationService delegate;

    protected ReservationServiceDecorator(IReservationService delegate) {
        this.delegate = delegate;
    }

    @Override
    public Reservation create(Reservation reservation) {
        return delegate.create(reservation);
    }

Le champ final delegate contient un objet qui respecte IReservationService. Le constructeur fixe le délégué à la construction et chaque méthode transmet son appel. Cet extrait montre le champ, le constructeur et create. Les quatre autres méthodes du même fichier suivent la même structure. Cette base évite de réécrire toute la délégation dans chaque décorateur concret. Elle n’ajoute aucune règle métier et ne porte pas d’annotation Spring. Code complet de la base :

package tn.esprit.autoloc.autolocapi.service.decorator;

import java.util.List;

import tn.esprit.autoloc.autolocapi.domain.Reservation;
import tn.esprit.autoloc.autolocapi.service.IReservationService;

/** Base du patron Décorateur : conserve le contrat et délègue les opérations. */
public abstract class ReservationServiceDecorator implements IReservationService {

    protected final IReservationService delegate;

    protected ReservationServiceDecorator(IReservationService delegate) {
        this.delegate = delegate;
    }

    @Override
    public Reservation create(Reservation reservation) {
        return delegate.create(reservation);
    }

    @Override
    public Reservation findById(Long id) {
        return delegate.findById(id);
    }

    @Override
    public List<Reservation> findAll() {
        return delegate.findAll();
    }

    @Override
    public Reservation update(Long id, Reservation reservation) {
        return delegate.update(id, reservation);
    }

    @Override
    public void deleteById(Long id) {
        delegate.deleteById(id);
    }
}


